git diff --exit-code package-lock.json || {
  echo "::error::package-lock.json drifted from package.json. Run 'npm install' locally and commit the regenerated lockfile. (This failure is a REAL lockfile mismatch — the install step succeeded, so no transient-network suspicion.)"
  exit 1
}

# PB-CI-002: lockstep versioning means EVERY publishable
# packages/*/package.json must equal TAG_VERSION, not just the root.
# The root-only check above can pass while a botched per-package bump
# leaves one workspace at a stale version — which would then publish
# the wrong version with a green workflow. ci.yml's sync-version gate
# would catch this, but ci.yml does not trigger on tag pushes, so the
# guarantee must be re-asserted here at release time. The check
# reads only NON-private packages (every one release.yml ships;
# `private:true` portfolio is workspace-internal and never published).
TAG_VERSION="${PUBLISH_TAG#v}"
node -e '
  const { readdirSync, readFileSync, existsSync } = require("node:fs");
  const { join } = require("node:path");
  const tag = process.argv[1];
  let bad = 0;
  for (const e of readdirSync("packages", { withFileTypes: true })) {
    if (!e.isDirectory()) continue;
    const p = join("packages", e.name, "package.json");
    if (!existsSync(p)) continue;
    const pkg = JSON.parse(readFileSync(p, "utf8"));
    if (pkg.private === true) continue;
    if (pkg.version !== tag) {
      console.log(`::error file=${p}::publishable package ${pkg.name} is at version ${pkg.version} but the release tag is ${tag} — lockstep versions drifted. Fix the bump (npm run sync-version) and re-tag.`);
      bad++;
    } else {
      console.log(`ok: ${pkg.name}@${pkg.version}`);
    }
  }
  if (bad > 0) process.exit(1);
' "${TAG_VERSION}"

node <<'NODE' > scenario-results.json
const conclusion = process.env.CI_CONCLUSION || 'success';
const runUrl = process.env.CI_RUN_URL
  || `${process.env.GITHUB_SERVER_URL}/${process.env.GITHUB_REPOSITORY}/actions/runs/${process.env.GITHUB_RUN_ID}`;
const verdict = conclusion === 'success' ? 'pass' : 'fail';
const status = verdict; // per-step status mirrors the gate outcome
const stepIds = [
  'version-sync-gate',
  'doc-drift-gate',
  'regression-pins-gate',
  'build',
  'scripts-suite',
  'workspace-suites',
];
const result = [{
  scenario_id: 'self-verify-gate',
  scenario_name: 'testing-os self-verification gate',
  scenario_version: '1.0.0',
  product_surface: 'cli',
  execution_mode: 'bot',
  verdict,
  notes: `Derived from the testing-os CI workflow_run conclusion: ${conclusion}.`,
  step_results: stepIds.map((step_id) => ({ step_id, status })),
  evidence: [{
    kind: 'log',
    description: 'The testing-os CI workflow_run log for the commit under test',
    url: runUrl,
  }],
}];
process.stdout.write(JSON.stringify(result, null, 2) + '\n');
NODE
echo "Built scenario-results.json for CI conclusion: ${CI_CONCLUSION:-success}"
